fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only parent nodes from 0 to floor(n/2) - 1 need checking
    let last_parent = n / 2; // integer division truncates, equivalent to floor(n/2)

    for i in 0..last_parent {
        let left_idx = 2 * i + 1;
        let right_idx = 2 * i + 2;

        // Check left child if it exists
        if left_idx < n && a[left_idx] < a[i] {
            return false;
        }

        // Check right child if it exists
        if right_idx < n && a[right_idx] < a[i] {
            return false;
        }
    }

    true
}